<section class="section"><div class="container"><h1 class="section-title">域名分发</h1><p class="section-sub">选择根域名并查询可用的子域名前缀</p><form class="domain-search d-flex gap-2 mb-4" method="get"><input class="form-control" name="prefix" value="<?= h($prefix) ?>" placeholder="例如 cloud"><button class="btn btn-primary">查询</button></form><div class="row g-3"><?php foreach ($domains as $domain): ?><div class="col-md-6 col-xl-4"><div class="card p-4 h-100"><h2 class="h5"><?= h($domain['domain']) ?></h2><div class="text-muted mb-3"><?= (float)$domain['price'] > 0 ? money($domain['price']) : '免费' ?> · 库存 <?= (int)$domain['stock'] > 0 ? (int)$domain['stock'] - (int)$domain['sold'] : '不限' ?></div><a class="btn btn-outline-primary" href="<?= h(url_to('index/dns/register', ['domain_id' => $domain['id'], 'prefix' => $prefix])) ?>">申请子域名</a></div></div><?php endforeach; ?></div><?php if (!$domains): ?><div class="empty">暂无可用根域名</div><?php endif; ?></div></section>
